using System.Collections.Generic;
using UnityEngine;

namespace LittleMusicWorld.Audio
{
    /// <summary>Every playable instrument (Resources/InstrumentLibrary). Generated by the editor setup.</summary>
    [CreateAssetMenu(menuName = "Little Music World/Instrument Library")]
    public sealed class InstrumentLibrary : ScriptableObject
    {
        public List<InstrumentDefinition> instruments = new List<InstrumentDefinition>();

        private Dictionary<string, InstrumentDefinition> byId;

        public InstrumentDefinition Get(string id)
        {
            if (string.IsNullOrEmpty(id)) return null;
            if (byId == null || byId.Count != instruments.Count)
            {
                byId = new Dictionary<string, InstrumentDefinition>();
                foreach (InstrumentDefinition d in instruments) if (d != null) byId[d.id] = d;
            }
            return byId.TryGetValue(id, out InstrumentDefinition def) ? def : null;
        }

        public IEnumerable<InstrumentDefinition> InFamily(InstrumentFamily family)
        {
            foreach (InstrumentDefinition d in instruments) if (d != null && d.family == family) yield return d;
        }

        private static InstrumentLibrary s_Instance;
        public static InstrumentLibrary Instance => s_Instance != null ? s_Instance : s_Instance = Resources.Load<InstrumentLibrary>("InstrumentLibrary");
    }
}
